46: function makeGene(rng,i){let [name,role]=FUNCTIONS[i%FUNCTIONS.length], codonN=5+rng.int(8), coding='ATG';for(let j=1;j<codonN-1;j++)coding+=rng.pick(CODONS.slice(1));coding+='TAA';let intron='';for(let j=0;j<20+rng.int(35);j++)intron+='ATCG'[rng.int(4)];let exonStart=100+rng.int(140), promoter='TATAAA';let regulation=['constitutive','nutrient-responsive','stress-inducible','developmental'][rng.int(4)];return{id:`G${String(i+1).padStart(2,'0')}`,name,role,chromosome:1+rng.int(3),start:exonStart,end:exonStart+coding.length+intron.length+16,promoter,enhancer:rng.pick(['CAAT','GC-box','HSE','CRE']),coding,intron,regulation,activity:.34+rng.next()*.62,dominance:rng.pick(['dominant','recessive','additive']),mutation:null,epi:rng.next()*.14}}
47: function makeGenome(seed,source=null){let rng=new RNG(hashSeed(seed)),genes=source?source.genes.map(g=>({...g})):Array.from({length:8+rng.int(4)},(_,i)=>makeGene(rng,i));let noncoding='';for(let i=0;i<120;i++)noncoding+='ATCG'[rng.int(4)];return{id:`GX-${hashSeed(seed).toString(16).toUpperCase().slice(0,6)}`,seed,chromosomes:source?source.chromosomes:2+rng.int(3),genes,noncoding,sequence:'',generation:source?.generation||0,origin:source?.id||null,mutations:source?source.mutations||0:0}}
48: function transcribe(g){return g.coding.replaceAll('T','U')}
49: function translate(rna){const aa=['M','A','F','E','Q','W','N','L','D','Y','P','K','V','S','T','R','L','Q','G'];let out='';for(let i=0;i<rna.length-3;i+=3){let c=rna.slice(i,i+3);if(c==='UAA'||c==='UAG'||c==='UGA')break;out+=aa[hashSeed(c)%aa.length]}return out||'M'}
50: function gc(seq){return seq?((seq.match(/[GC]/g)||[]).length/seq.length*100):0}
51: function genomeSequence(g){let s='';for(const gene of g.genes){s+=gene.promoter+gene.enhancer+gene.coding.slice(0,Math.floor(gene.coding.length/2))+gene.intron+gene.coding.slice(Math.floor(gene.coding.length/2))}return s+g.noncoding}
52: function environmentStress(env){return clamp(Math.abs(env.temperature-24)/22+env.radiation*.7+env.chemical*.5+Math.abs(env.ph-7.3)*.1,0,1.4)}
53: function traitMap(g,env){let map={},stress=environmentStress(env);for(const gene of g.genes){let envFactor=1;if(gene.regulation==='stress-inducible')envFactor=clamp(.24+stress*.95,.18,1);if(gene.regulation==='nutrient-responsive')envFactor=clamp(.22+env.nutrients*.9,.2,1);if(gene.regulation==='developmental')envFactor=.45+Math.sin(g.generation*.11)*.2;map[gene.name]=clamp(gene.activity*envFactor*(1-gene.epi)*(gene.mutation?.8:1),.02,1)}return map}
54: function expressionProfile(g,env){const exp=traitMap(g,env);return g.genes.map(x=>({...x,expression:exp[x.name],protein:translate(transcribe(x))}))}
55: function makePlateState(genome,seed,viability,atp,count=12,archived=false){let rng=new RNG(hashSeed(`${seed}:plate`)),source=JSON.parse(JSON.stringify(genome)),cells=[];for(let i=0;i<count;i++)cells.push({id:`CELL-${String(i+1).padStart(3,'0')}`,genomeId:genome.id,viability:clamp(viability+rng.normal()*2.2,35,100),atp:clamp(atp+rng.normal()*.12,.2,7),damage:clamp((100-viability)*.08+rng.next()*2,0,100),ros:clamp(rng.next()*8,0,100),membrane:clamp(96+rng.normal()*1.5,0,100),proteinLoad:clamp(rng.next()*8,0,100),state:'cycling',generation:genome.generation||0,archived,sourceLabel:archived?'ARCHIVE':'LIVE CULTURE',x:12+rng.next()*76,y:14+rng.next()*72,phase:rng.next()*6.28,cycleProgress:rng.next()*.72,age:0,divisions:0,stained:false,entityKind:'cell'});return{plate:cells,plateSources:{[genome.id]:source},plateSequence:count,selectedCellId:cells[0]?.id||null}}
56: function makePresetPlate(key){let preset=PLATE_PRESETS[key]||PLATE_PRESETS.rat,rng=new RNG(hashSeed(`${S.seed}:${key}:preset`)),count=12,plate=[];if(preset.kind==='cell')return{...makePlateState(S.genome,`${S.seed}:${key}`,S.viability,S.atp,count),platePreset:key};for(let i=0;i<count;i++)plate.push({id:`VIRION-${String(i+1).padStart(3,'0')}`,genomeId:S.genome.id,entityKind:'virus',archived:false,sourceLabel:'FREE VIRION',x:12+rng.next()*76,y:14+rng.next()*72,phase:rng.next()*6.28,elementExposures:{}});return{plate,plateSources:{[S.genome.id]:JSON.parse(JSON.stringify(S.genome))},plateSequence:count,selectedCellId:plate[0]?.id||null,platePreset:key}}
57: function loadPlatePreset(key){if(!PLATE_PRESETS[key])return;Object.assign(S,makePresetPlate(key));S.platePreset=key;storeState();render();toast(`${PLATE_PRESETS[key].label} loaded · ${PLATE_PRESETS[key].kind==='virus'?'free virions; no infection or division modeled':'illustrative cellular preset'}.`)}
58: function activePlatePreset(){return PLATE_PRESETS[S.platePreset]||null}
59: function initialState(seed,source){let rng=new RNG(hashSeed(seed)),genome=makeGenome(seed,source),env={temperature:20+rng.next()*12,radiation:rng.next()*.18,nutrients:.45+rng.next()*.5,oxygen:.42+rng.next()*.55,water:.45+rng.next()*.5,ph:6.4+rng.next()*1.8,chemical:0};genome.sequence=genomeSequence(genome);let exp=traitMap(genome,env),fitness=clamp(.62+Object.values(exp).reduce((a,b)=>a+b,0)/Object.keys(exp).length*.2-rng.next()*.12,.3,.95);return{seed,genome,env,tick:0,generation:0,population:120+rng.int(280),fitness,viability:91+rng.next()*8,atp:2.1+rng.next()*1.3,damage:rng.next()*7,senescence:rng.next()*4,diversity:.08+rng.next()*.12,history:[],events:[{tick:0,type:'origin',text:'A viable population establishes in the tidal microhabitat.'}],samples:{dna:false,rna:false},labResults:[],notebook:[],archive:[],speed:1,playing:false,selectedGene:0,cellCount:2400+rng.int(700),liveCells:0,sourceId:source?.id||null,experimentCount:0,researchXP:0,researchLevel:1,...makePlateState(genome,seed,91,2.7)}}
60: function storeState(){try{const {playing,...safe}=S;localStorage.setItem(STORAGE_KEY,JSON.stringify(safe))}catch(e){console.warn('Persistence unavailable',e)}}
61: function loadState(){try{let x=JSON.parse(localStorage.getItem(STORAGE_KEY));if(x?.genome){x.playing=false;return x}}catch(e){}return null}
62: let S=loadState()||initialState(`GEN-${Date.now().toString(36)}-${Math.random().toString(36).slice(2,7)}`);
63: if(!Array.isArray(S.plate)){Object.assign(S,makePlateState(S.genome,S.seed,S.viability||90,S.atp||2.5))}S.plateSources=S.plateSources||{[S.genome.id]:JSON.parse(JSON.stringify(S.genome))};S.plateSequence=S.plateSequence||S.plate.length;for(const c of S.plate){c.damage=c.damage??Math.max(0,100-c.viability)*.08;c.cycleProgress=c.cycleProgress??0;c.age=c.age??0;c.divisions=c.divisions??0;c.stained=c.stained??false;c.ros=c.ros??0;c.membrane=c.membrane??clamp(100-(c.damage||0)*.35,0,100);c.proteinLoad=c.proteinLoad??0;c.state=c.state||'cycling';c.stainIntensity=c.stainIntensity??null;c.elementExposures=c.elementExposures&&typeof c.elementExposures==='object'&&!Array.isArray(c.elementExposures)?c.elementExposures:{}}S.selectedCellId=S.selectedCellId||S.plate[0]?.id||null;S.selectedElement=ELEMENTS.some(e=>e.symbol===S.selectedElement)?S.selectedElement:'C';S.researchXP=Number.isFinite(S.researchXP)?Math.max(0,S.researchXP):0;S.researchSuccesses=Math.max(0,Number(S.researchSuccesses)||0);S.researchLevel=Number.isSafeInteger(S.researchLevel)&&S.researchLevel>=1?S.researchLevel:1;while(S.researchXP>=S.researchLevel*100&&Number.isFinite(S.researchLevel))S.researchXP-=S.researchLevel++*100;
64: function codexUnlocked(){return S.plate.length>0&&S.researchSuccesses>0}
65: function recordResearchSuccess(label){S.researchSuccesses=(S.researchSuccesses||0)+1;S.researchXP=(S.researchXP||0)+100;let oldLevel=S.researchLevel||1;while(S.researchXP>=S.researchLevel*100)S.researchXP-=S.researchLevel++*100;return{level:S.researchLevel,leveled:S.researchLevel>oldLevel,label}}
