6: function hashSeed(s){let h=2166136261;for(const c of String(s)){h^=c.charCodeAt(0);h=Math.imul(h,16777619)}return h>>>0}
7: class RNG{constructor(seed){this.s=seed>>>0||1}next(){this.s=(Math.imul(this.s,1664525)+1013904223)>>>0;return this.s/4294967296}int(n){return Math.floor(this.next()*n)}pick(a){return a[this.int(a.length)]}normal(){return Math.sqrt(-2*Math.log(Math.max(.000001,this.next())))*Math.cos(6.283*this.next())}}
