function labView(){let req=activeProtocol==='DNA extraction'?'Ready for extraction':S.samples.dna?'DNA extract available':'Sample available · extract DNA first';return `${pageHead(`EXPERIMENTAL SUITE · PROTOCOL ${String(S.experimentCount+1).padStart(3,'0')}`,'Wet lab','Run simplified, traceable procedures against your organism’s actual genome.',`<span class="tag ${S.samples.dna?'green':''}">${req.toUpperCase()}</span>`)}<div class="section-grid"><section class="card"><div class="card-head"><span class="card-title">Protocol library</span><span class="card-meta">12 METHODS · MODELLED</span></div><div class="protocol-grid">${PROTOCOLS.map(p=>`<button class="protocol-option ${activeProtocol===p[0]?'selected':''}" data-protocol="${p[0]}"><div class="protocol-icon">${p[1]}</div><strong>${p[0]}</strong><p>${p[2]}</p><small>${p[3]}</small></button>`).join('')}</div></section><div style="display:grid;gap:14px;align-content:start"><section class="card"><div class="card-head"><span class="card-title">Bench configuration</span><span class="card-meta">${activeProtocol.toUpperCase()}</span></div><div class="gene-detail"><div class="mini-stat"><span>SUBJECT / REFERENCE</span><strong>${S.genome.id}<small> · generation ${S.generation}</small></strong></div><label class="modal-label" style="display:block;font:9px var(--mono);color:#829188;margin:17px 0 6px">TARGET LOCUS</label><select class="select-button" id="target-gene" style="width:100%">${S.genome.genes.map(g=>`<option value="${g.id}">${g.id} · ${g.name}</option>`).join('')}<option value="whole">Whole genome</option></select><div class="chip-row"><span class="chip">SAMPLE ${S.samples.dna?'DNA EXTRACTED':'LIVE CULTURE'}</span><span class="chip">REPLICATE n=1</span></div><button class="action-button primary" style="width:100%;margin-top:6px" data-action="run-lab">▶ &nbsp; Run ${activeProtocol}</button></div></section><section class="card"><div class="card-head"><span class="card-title">Latest result</span><span class="card-meta">$