function evolutionView(){let rows=S.history.slice(-12).reverse().map(x=>`<div class="timeline-row"><span class="timeline-gen">GEN ${String(x.generation).padStart(3,'0')}</span><div class="timeline-bar"><i style="width:${Math.max(4,x.fitness*100)}%"></i></div><span class="timeline-fit">${f(x.fitness*100,1)}% · ${x.population}</span></div>`).join('');let traits=expressionProfile(S.genome,S.env).slice(0,5),lineageCells=S.plate.filter(c=>(c.generation||0)>0||c.mutationCount>0),latest=lineageCells.slice(-1)[0],mutationTotal=lineageCells.reduce((sum,c)=>sum+(c.mutationCount||0),0);return `${pageHead(`POPULATION DYNAMICS · ${S.generation} GENERATIONS`,'Evolution','Inheritance, selection and drift unfold under changing conditions.',`<button class="subtle-button" data-action="evolve">⤴ Advance 10 generations</button><button class="action-button primary" data-action="toggle">${S.playing?'Ⅱ Pause':'▶ Resume'}</button>`)}<div class="metric-strip">${metric('GENERATION',String(S.generation).padStart(3,'0'),'reproductive cycles')}${metric('POPULATION',S.population.toLocaleString(),'individuals · effective proxy')}${metric('RELATIVE FITNESS',`${f(S.fitness*100,1)}%`,'environment-relative index')}${metric('MUTATION RATE',`${f(.1+S.env.radiation*.8,2)}%`,'per locus · model assumption')}</div><div class="section-grid"><section class="card"><div class="card-head"><span class="card-title">Lineage fitness</span><span class="card-meta">SELECTION HISTORY · LAST 12</span></div><div class="timeline">${rows||'<div class="empty-state">No generation events yet. Resume or advance the simulation.</div>'}</div></section><section class="card"><div class="card-head"><span class="card-title">Population composition</span><span class="card-meta">PHENOTYPE PROXIES</span></div><div class="population-bars">${traits.map((g,i)=>`<div class="pop-row"><span>${g.name.split(' ')[0]}</span><div class="pop-track"><i style="width:${g.expression*100}%"></i></div><span>${f(g.expression*100,0)}%</span></div>`).join('')}<p style="font-size:9px;color:#75857b;margin:18px 0 0">Trait frequencies approximate expression prevalence; this is not an individual-based population-genetics model.</p></div></section></div><section class="card" style="margin-top:14px"><div class="card-head"><span class="card-title">Plate lineage</span><span class="card-meta">HERITABLE DIVISION RECORDS</span></div><div class="gene-detail"><div class="chip-row"><span class="chip">${lineageCells.length} MUTANT CELLS</span><span class="chip">${mutationTotal} CUMULATIVE MUTATIONS</span><span class="chip">${latest?`LATEST ${latest.id} · GEN ${latest.generation}`:'NO DAUGHTER LINEAGES YET'}</span></div><p>${latest?`${latest.id} descends from ${latest.parentGenomeId||'the founding genome'} through deterministic plate division. Child genome ${latest.genomeId} carries ${latest.mutationCount||0} coding mutation${(latest.mutationCount||0)===1?'':'s'}.`:'Advance a viable cell through the cell-cycle checkpoint to create a heritable daughter genome and lineage record.'}</p></div></section><section class="card" style="margin-top:14px"><div class="card-head"><span class="card-title">Environmental conditions</span><span class="card-meta">CHANGES AFFECT REGULATORY EXPRESSION & FITNESS</span></div><div class="env-grid">${[['temperature','Temperature','°C',0,40],['radiation','Radiation','relative',0,1],['nutrients','Nutrient availability','fraction',0,1],['oxygen','Oxygen availability','fraction',0,1],['water','Water availability','fraction',0,1],['ph','pH','',4,10],['chemical','Chemical stress','relative',0,1]].map(([key,label,unit,min,max])=>`<div class="env-control"><label><span>${label}</span><b>${f(S.env[key],1)} ${unit}</b></label><input type="range" min="${min}" max="${max}" step=".1" value="${S.env[key]}" data-env="${key}" /></div>`).join('')}</div></section>`}

