ionDetails.map(m=>`${m.name} ${m.from}→${m.to} at coding position ${m.position}`).join(' · '):'No coding mutations recorded for this genome.'}</p></div></section>`:''}<div class="section-grid"><section class="card"><div class="card-head"><span class="card-title">Gene annotation <span class="card-meta">/ ${genome.genes.length} loci</span></span><span class="tag green">LIVE EXPRESSION</span></div><div class="gene-list">${geneRows()}</div></section><div style="display:grid;gap:14px;align-content:start"><section class="card"><div class="card-head"><span class="card-title">Locus sequence · ${g.id}</span><span class="tag">CHROMOSOME ${g.chromosome}</span></div><div class="gene-detail"><div class="sequence-display"><div>${sequence}</div><div class="sequence-caption"><span>5′ → 3′ · CODING STRAND</span><span>${slice.length} BP</span></div></div><div class="chip-row"><span class="chip">PROMOTER ${g.promoter}</span><span class="chip">ENHANCER ${g.enhancer}</span><span class="chip">${g.intron.length} BP INTRON</span></div><p><strong style="color:#dce4dd">${g.name}</strong> — ${g.role}. ${g.regulation} regulation. Predicted peptide: <span style="color:var(--lime);font-family:var(--mono)">${translate(transcribe(g))}</span></p><div class="mini-stat"><span>EXPRESSION LEVEL · RELATIVE MODEL UNITS</span><strong class="stat-good">${f(traitMap(genome,S.env)[g.name],3)}<small>× baseline</small></strong></div></div></section><section class="card"><div class="card-head"><span class="card-title">Sequence context</span><span class="card-meta">NON-CODING DNA</span></div><div class="gene-detail"><div class="sequence-display">${S.genome.noncoding.slice(0,84).split('').map((x,i)=>`<span style="color:${['#9bafa3','#9bd8c3','#d0b77e','#a6c078'][i%4]}">${x}</span>`).join('')}<div class="sequence-caption"><span>INTERGENIC REGION</span><span>84 BP SHOWN</span></div></div><p>Non-coding sequence contributes regulatory context in this model; sequence shown is generated, not a reference biological genome.</p></div></section></div></div>`}

