function cellView(){if(!S.plate?.length)Object.assign(S,makePlateState(S.genome,S.seed,S.viability,S.atp,0));let selected=S.plate.find(c=>c.id===S.selectedCellId)||S.plate[0],genome=plateGenome(selected),traits=traitMap(genome,S.env),atpExpression=traits['ATP synthase']||.5,stage=cycleStage(selected.cycleProgress||0),checkpoint=cycleCheckpoint(selected),organelles=[['Cell membrane',`${f(selected.membrane,1)}% integrity · transport boundary`],['Cytoplasm',`${f(atpExpression*100,0)}% metabolic activity`],['Nucleus',`${genome.genes.length} annotated loci · ${genome.id}`],['Mitochondria',`${f(selected.atp,2)} mmol/L ATP proxy · ROS ${f(selected.ros,1)}`],['Ribosomes',`${genome.genes.length} active transcript targets`],['Endoplasmic reticulum',`${f((traits['Heat-shock protein']||.5)*100,0)}% folding response · load ${f(selected.proteinLoad,1)}%`],['Golgi apparatus','Protein processing'],['Lysosomes','Turnover · autophagy proxy'],['Cytoskeleton',`${selected.archived?'archived':'live'} lineage · generation ${selected.generation}`],['Cell receptors',`${f((S.env.nutrients+.2)*7,1)} relative signal capacity`]];return `${pageHead(`LIVE IMAGING · CELL ${String(S.tick%9999).padStart(4,'0')}`,'Cell observatory','Every pulse reflects the selected cell’s genome and measured state.',`<button class="subtle-button" data-action="plate-live">＋ Add live cells</button><button class="subtle-button" data-action="cell-cycle">↻ Advance cell cycle</button><button class="subtle-button" data-action="stain">◉ Stain selected</button>`)}<section class="card plate-card"><div class="card-head"><div><span class="card-title">Observatory plate <span class="card-meta">/ CULTURE DISH · ${S.plate.length} OF 30 CELLS</span></span><div class="plate-caption">Select any cell to inspect it. Pulse rate and hue are derived from its expressed genome.</div></div><span class="tag green">${S.plate.length} ON PLATE</span></div><div class="plate-stage"><div class="plate-dish"><div class="plate-rim"></div><div class="pl